dynamic-sql.select:
SELECT id, name, age, email, phone, dept_id, create_time, update_time
FROM sys_user


        AND name LIKE CONCAT('%', #{name}, '%')


        AND age >= #{minAge}


        AND dept_id = #{deptId}


ORDER BY id ASC

SELECT COUNT(1) AS total_count
FROM sys_user


        AND name LIKE CONCAT('%', #{name}, '%')


        AND age >= #{minAge}


        AND dept_id = #{deptId}
